"""The shop's worlds are generated by the core's families from the declared scenario.

These tests run no agent: they check what the declaration yields (validity, roles, observability,
what the oracle cannot judge), that the generic families name nothing of the shop, and the
stochastic behavior of a deliberately flaky scripted agent.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

import pytest

from isitright.core.constraints import ValidityStatus
from isitright.core.oracles import Role
from isitright.core.stochastic import Budget
from isitright.packs.mcp.audit import run_scenario
from isitright.packs.mcp.generate import GeneratedWorld, generate_worlds, select_worlds
from isitright.packs.mcp.model import McpScenario, ScenarioError, load_scenario

EXAMPLES = Path(__file__).parents[1] / "examples" / "agents"
SHOP_REF = f"{EXAMPLES / 'shop' / 'scenario.py'}:SCENARIO"
BOOKING_REF = f"{EXAMPLES / 'booking_scenario.py'}:SCENARIO"
FLAKY = f'"{sys.executable}" "{EXAMPLES / "flaky_agent.py"}"'


@pytest.fixture(scope="module")
def shop() -> McpScenario:
    return load_scenario(SHOP_REF)


@pytest.fixture(scope="module")
def level_one(shop: McpScenario) -> list[GeneratedWorld]:
    worlds, _ = generate_worlds(shop, attempts=3000, depth=1)
    return worlds


def test_the_hints_come_with_provenance_and_resolve_in_the_entity_model(shop: McpScenario) -> None:
    by_name = {h.name: h.provenance.value for h in shop.hints}
    assert by_name == {
        "lookup": "declared",
        "ordering": "declared",
        "gate": "declared",
        "scope": "declared",
        "item_price": "harvested:trace",
        "item_qty": "harvested:trace",
        "page_size": "harvested:schema",
        "trace": "harvested:trace",
    }
    trace = shop.hints.get("trace")
    assert trace is not None and [c["tool"] for c in trace.args["calls"]][:3] == [
        "find_customer",
        "list_orders",
        "get_order",
    ]


def test_a_hint_that_does_not_resolve_is_an_error_at_load(shop: McpScenario) -> None:
    from isitright.core.hints import Hint, Hints

    bad = Hints([Hint(kind="ordering", args={"collection": "orders", "field": "created"})])
    with pytest.raises(ScenarioError, match="no field 'created'"):
        McpScenario(
            id="s",
            task="t",
            spec=shop.spec,
            tools=shop.tools,
            base=shop.base,
            layout=shop.layout,
            oracle=shop.oracle,
            hints=bad,
        )


def test_generated_worlds_are_valid_and_carry_the_hints_that_led_to_them(
    shop: McpScenario, level_one: list[GeneratedWorld]
) -> None:
    assert len(level_one) > 80
    for world in level_one:
        assert shop.spec.validate(world.world.state).status is ValidityStatus.VALID
        assert "STRUCTURAL" in world.tiers
        # A JSON edit has no rule over the content in the shop, so it is STRUCTURAL only and says
        # so; every other generated world keeps the tier (was: every world had both tiers).
        if "json_edit" in world.families:
            assert "DOMAIN_VALIDATED" not in world.tiers and world.notes
        else:
            assert "DOMAIN_VALIDATED" in world.tiers
    hinted = [w for w in level_one if w.group == "hinted"]
    assert hinted and all(m.hints for w in hinted for m in w.world.path[:1])
    # Collection sizes at the schema's page size, a status next to the gate, ties on the ordering.
    families = {f for w in level_one for f in w.families}
    assert {
        "key_collision",
        "cardinality_boundary",
        "tie",
        "split",
        "representation",
        "prior_operation",
        "response_edit",
        "timing",
        "empty",
        "dangling",
        "out_of_scope_extreme",
        "service_parameter",
    } <= families


def test_roles_come_from_the_reference_procedure_and_both_kinds_exist(
    level_one: list[GeneratedWorld],
) -> None:
    roles = {w.role for w in level_one}
    assert {Role.CONTROL, Role.TRAP, Role.UNJUDGEABLE} <= roles
    for w in level_one:
        assert w.role_basis


def test_a_change_to_a_field_no_read_tool_shows_is_flagged_unobservable(
    level_one: list[GeneratedWorld],
) -> None:
    refund_only = [
        w
        for w in level_one
        if w.families == ["prior_operation"]
        and w.world.path[0].description.startswith("prior operation refund_in")
    ]
    assert refund_only and all("OBSERVABLE" not in w.tiers for w in refund_only)
    assert all("REACHABLE" in w.tiers for w in refund_only)
    cancelled = [
        w
        for w in level_one
        if w.families == ["prior_operation"]
        and w.world.path[0].description.startswith("prior operation cancel_order")
    ]
    assert cancelled and all("OBSERVABLE" in w.tiers for w in cancelled)


def test_an_ownership_change_during_the_run_is_reported_as_cannot_judge(
    level_one: list[GeneratedWorld],
) -> None:
    swaps = [
        w
        for w in level_one
        if w.families == ["timing"] and ".customer_id now points at" in w.world.path[0].description
    ]
    assert swaps
    assert all(w.role is Role.UNJUDGEABLE and w.unjudgeable for w in swaps)
    assert "assumptions" in swaps[0].unjudgeable  # type: ignore[operator]


def test_generation_is_deterministic_for_a_seed(shop: McpScenario) -> None:
    a, _ = generate_worlds(shop, attempts=800, depth=2, seed=5)
    b, _ = generate_worlds(shop, attempts=800, depth=2, seed=5)
    assert [w.id for w in a] == [w.id for w in b]
    assert [w.world.fingerprint() for w in a] == [w.world.fingerprint() for w in b]


def test_depth_two_composes_a_second_mutation_on_what_the_first_created(shop: McpScenario) -> None:
    worlds, result = generate_worlds(shop, attempts=6000, depth=2, seed=1)
    assert result.accounting()["depth_reached"] == 2
    composed = [w for w in worlds if len(w.world.path) == 2]
    assert composed
    colliding = [
        w
        for w in composed
        if [m.family for m in w.world.path] == ["key_collision", "duplicate"]
        and "matches the same lookup" in w.world.path[1].description
    ]
    assert colliding  # a second customer with a newer order, from two generic mutations


def test_at_least_one_valid_world_that_no_author_wrote(
    shop: McpScenario, level_one: list[GeneratedWorld]
) -> None:
    written = {
        shop.layout.from_service(w.build(), shop.base.keys).fingerprint() for w in shop.fixed_worlds
    }
    new = [w for w in level_one if w.world.state.fingerprint() not in written and w.world.path]
    assert new
    assert all(w.tiers for w in new)


def test_generic_families_name_nothing_of_the_shop() -> None:
    """No family may hard-code a shop field, value or world: only hints and the schema name them.

    Checks identifiers and string literals of the core (not docstrings, which explain in words).
    """
    import ast

    source = Path(__file__).parents[1] / "src" / "isitright" / "core"
    tokens = (
        "Maria",
        "10027",
        "pm_",
        "shipped",
        "processing",
        "refund",
        "customers",
        "payments",
        "orders",
        "created_at",
        "page_size",
        "cancel_order",
    )
    found: list[str] = []
    for path in source.rglob("*.py"):
        tree = ast.parse(path.read_text(encoding="utf-8"))
        docstrings = {
            id(node.body[0].value)
            for node in ast.walk(tree)
            if isinstance(node, ast.Module | ast.ClassDef | ast.FunctionDef)
            and node.body
            and isinstance(node.body[0], ast.Expr)
            and isinstance(node.body[0].value, ast.Constant)
        }
        for node in ast.walk(tree):
            text = None
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                text = None if id(node) in docstrings else node.value
            elif isinstance(node, ast.Name):
                text = node.id
            if text and any(re.search(rf"{re.escape(t)}", text) for t in tokens):
                found.append(f"{path.name}: {text[:40]!r}")
    assert found == []


# --- the stochastic check: a flaky scripted agent with a simulated cost -------------------


def test_flaky_agent_run_counts_no_rate_claim_and_a_money_budget(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.setenv("FLAKY_AGENT_COST", "0.1")
    report = run_scenario(
        scenario_ref=BOOKING_REF,
        agent_command=FLAKY,
        output_dir=tmp_path / "out",
        worlds="fixed",
        only=["booked_24h_01m", "booked_23h_59m"],
        k=4,
        budget=Budget(money=0.85),
        trust_code=True,
        timeout_seconds=120,
    )
    case = report.cases[0]
    runs = case.extensions["mcp"]["runs"]
    # A money budget of 0.85 stops the search after 9 runs of 0.1 (0.9 spent): the baseline
    # gets all 4 runs, the next world 4, the last world only 1.
    assert len(runs) == 9
    per_world = {w.id: w.counts["n"] for w in case.worlds}
    assert per_world["baseline"] == 4 and per_world["booked_24h_01m"] == 4
    assert per_world["booked_23h_59m"] == 1
    assert case.search.budget["runs"]["stopped_by"] == "money"
    assert case.search.budget["runs"]["spent"]["money"] == pytest.approx(0.9)
    # The baseline is itself flaky: careful on odd trials, careless on even trials.
    assert case.stability is not None and case.stability.baseline is not None
    assert case.stability.baseline.met == 2 and case.stability.baseline.not_met == 2
    assert "flaky" in case.stability.note
    # With 4 runs per arm there is not enough evidence for a rate claim, only counts.
    assert case.stability.rate_claim is None
    for finding in case.findings:
        assert finding.stability is not None and finding.stability.rate_claim is None
    trap = next(f for f in case.findings if f.world_id == "booked_24h_01m")
    assert trap.stability is not None and trap.stability.world is not None
    assert (trap.stability.world.n, trap.stability.world.violated) == (4, 2)
    assert trap.divergence["runs_affected"] == 2 and trap.divergence["runs_evaluated"] == 4
    assert trap.headline.endswith(
        "in 2 of 4 runs on world booked_24h_01m (attribution not assessed)"
    )
    data = json.loads((tmp_path / "out" / "report.json").read_text(encoding="utf-8"))
    assert data["cases"][0]["findings"][0]["stability"]["k"] == 4


def test_a_rate_claim_needs_enough_paired_runs_and_names_its_test(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.setenv("FLAKY_AGENT_COST", "0.0")
    report = run_scenario(
        scenario_ref=BOOKING_REF,
        agent_command=f'"{sys.executable}" -c "pass"',
        output_dir=tmp_path / "out",
        worlds="fixed",
        only=["booked_24h_01m"],
        k=8,
        trust_code=True,
        timeout_seconds=60,
    )
    case = report.cases[0]
    # Eight clean runs against eight clean runs: counts, no claim of a higher failure rate.
    assert case.stability is not None and case.stability.rate_claim is None
    assert case.stability.world is not None and case.stability.world.n == 8


def test_selection_covers_families_and_roles_and_reports_what_it_left_out(
    shop: McpScenario,
) -> None:
    worlds, _ = generate_worlds(shop, attempts=6000, depth=2, seed=1)
    chosen, totals = select_worlds(worlds, 25)
    assert len(chosen) == totals["selected"] == 25
    assert totals["generated"] == len(worlds) and totals["generated"] > 25
    assert all(w.role is not Role.UNJUDGEABLE and w.observable for w in chosen)
    assert totals["unjudgeable"] > 0
    assert totals["not_selected"] == totals["eligible"] - 25
    assert {w.role for w in chosen} == {Role.CONTROL, Role.TRAP}
    families = {m.family for w in chosen for m in w.world.path}
    available = {m.family for w in worlds if w.role is not Role.UNJUDGEABLE for m in w.world.path}
    assert len(families) >= min(10, len(available))
    assert sum(totals["selected_by_family"].values()) == 25
    # Deterministic, and a larger limit extends the same picks in the same order.
    again, _ = select_worlds(worlds, 25)
    assert [w.id for w in again] == [w.id for w in chosen]
    assert select_worlds(worlds, None)[1]["selected"] == totals["eligible"]
    # Priority order: three single mutations, then a composition, so an early stop sees both.
    assert [len(w.world.path) for w in chosen[:4]] == [1, 1, 1, 2]
    assert totals["features_covered"] <= totals["features_total"]


def test_a_run_reports_the_totals_and_only_bypasses_selection(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    report = run_scenario(
        scenario_ref=SHOP_REF,
        agent_command=f'"{sys.executable}" "{EXAMPLES / "shop" / "scripted_agent.py"}"',
        output_dir=tmp_path / "out",
        worlds="generated",
        k=1,
        attempts=300,
        max_worlds=3,
        trust_code=True,
        timeout_seconds=60,
    )
    case = report.cases[0]
    selection = case.extensions["mcp"]["selection"]
    assert selection["run"] == 3 and selection["generated"] > 3 and selection["not_run"] > 0
    ran = [w for w in case.worlds if w.run_status == "RUN"]
    assert len(ran) == 4  # the baseline and three worlds
    not_run = [w for w in case.worlds if w.run_status == "NOT_RUN"]
    assert not_run and all(w.not_run_reason for w in not_run)  # listed as not run, with why
    assert any("safety rail" in w.not_run_reason for w in not_run if w.not_run_reason)
    assert any("ranked by diverse" in note for note in case.search.notes)
    assert case.search.screening is not None and case.search.screening.baseline_trace
    assert "selected" not in case.headline  # the headline stays about the evidence


